import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createNode as _ } from '@/primitives'; // placeholder to ensure '@/primitives' is imported (no side‑effects)

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group: CGroup, Mesh: CMesh, PlaneGeometry: CPlaneGeometry, MeshBasicNodeMaterial: CMeshBasicNodeMaterial } = ctx.THREE;

  // Root container (the adapter will apply position/rotation/scale)
  const root = new CGroup();

  // ---------- Plane ----------
  const planeGeom = new CPlaneGeometry(1, 1);
  const planeMat = new CMeshBasicNodeMaterial({ color: 0xffffff, map: null });
  const planeMesh = new CMesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load texture asynchronously – function stays synchronous
  const cleanup = { textures: [], primitives: [] };
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
      cleanup.textures.push(tex);
    });
  }

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  if (items.length) {
    const textGroup = new CGroup();
    for (const item of items) {
      const txtOpts = {
        fontSize: item.typography?.fontSize ?? 39,
        color: '#e8ecf2', // paper color for headline
        align: 'center',
        maxWidthPx: undefined,
        letterSpacingPx: undefined,
      };
      const txtObj = ctx.fontAtlas.createText(item.text ?? '', txtOpts);
      textGroup.add(txtObj);
    }
    root.add(textGroup);
  }

  // ---------- Cinematic Primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (typeof ctx.primitives[prim.name] === 'function') {
        const result = ctx.primitives[prim.name](root, prim.params);
        if (result && typeof result.cleanup === 'function') {
          cleanup.primitives.push(result);
        }
      }
    }
  }

  // ---------- UserData & Cleanup ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometry & material
    planeGeom.dispose();
    planeMat.dispose();

    // Dispose loaded textures
    for (const tex of cleanup.textures) {
      tex.dispose();
    }

    // Cleanup primitives and their timelines
    for (const prim of cleanup.primitives) {
      if (typeof prim.cleanup === 'function') prim.cleanup();
    }

    // Kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  return root;
}
